import { defineCollection } from "astro:content";
import { glob } from "astro/loaders";
import { z } from "astro/zod";

// Generated by `dex docs export` from trove/ — never edit by hand.
const items = defineCollection({
  loader: glob({
    base: "./src/content/items",
    pattern: "*.md",
    generateId: ({ entry }) => entry.replace(/\.md$/i, ""),
  }),
  schema: z.object({
    id: z.string(),
    kind: z.enum(["skill", "agent", "instruction", "prompt", "hook", "workflow", "plugin"]),
    namespace: z.string(),
    name: z.string(),
    title: z.string(),
    description: z.string().default(""),
    tags: z.array(z.string()).default([]),
    version: z.string(),
    license: z.object({
      spdx: z.string().nullable(),
      verdict: z.string(),
      evidence: z.string(),
      notice: z.string().default(""),
      components: z.array(z.string()).default([]),
    }),
    source: z.object({
      id: z.string(),
      title: z.string(),
      repo: z.string().nullable().optional(),
      commit: z.string().nullable().optional(),
      path: z.string(),
      url: z.string().nullable().optional(),
      author: z.string().nullable().optional(),
    }),
    inspired_by: z.array(z.object({ title: z.string(), url: z.string().optional() })).default([]),
    executes_code: z.boolean().default(false),
    members: z.array(z.string()).default([]),
    files: z.array(z.string()).default([]),
    apply_to: z.string().nullable().optional(),
    notes: z.array(z.string()).default([]),
    upstream_meta: z.array(z.object({ key: z.string(), value: z.string() })).default([]),
    hook_events: z
      .array(z.object({ event: z.string(), command: z.string(), timeout: z.string() }))
      .default([]),
    file_rows: z.array(z.object({ path: z.string(), size: z.number(), url: z.string() })).default([]),
    related: z.array(z.string()).default([]),
    part_of: z.array(z.string()).default([]),
    secret_flags: z.number().default(0),
    // Typed facets from trove/facets.json (docs/guides/finding-capabilities.md).
    facets: z.record(z.string(), z.union([z.string(), z.array(z.string())])).default({}),
    facet_sources: z.record(z.string(), z.string()).default({}),
    review_status: z.string().default("unknown"),
  }),
});

// The documentation is read straight from the repository's docs/ folder.
const docs = defineCollection({
  loader: glob({
    base: "../docs",
    pattern: "**/*.md",
    generateId: ({ entry }) => entry.replace(/\\/g, "/").replace(/\.md$/i, ""),
  }),
  schema: z.object({
    title: z.string().optional(),
    description: z.string().optional(),
  }),
});

export const collections = { items, docs };
